import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Heart, Sparkles, Crown, Flower2, Gem, PartyPopper } from "lucide-react";

const WEDDING_STYLES = [
  {
    id: "traditional",
    icon: Crown,
    title: "Traditional Elegance",
    desc: "Rich reds, golds, and ornate drapes",
    colors: ["#8B0000", "#D4AF37", "#FFD700"],
    image: "https://images.unsplash.com/photo-1519741497674-611481863552?w=600"
  },
  {
    id: "royal",
    icon: Gem,
    title: "Royal Palace",
    desc: "Velvet, crystal, and grand chandeliers",
    colors: ["#4A0E4E", "#C9A227", "#F5E6D3"],
    image: "https://images.unsplash.com/photo-1583939003579-730e3918a45a?w=600"
  },
  {
    id: "floral",
    icon: Flower2,
    title: "Floral Paradise",
    desc: "Soft pastels with abundant florals",
    colors: ["#FFB6C1", "#98D8C8", "#FFF8DC"],
    image: "https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=600"
  },
  {
    id: "modern",
    icon: Sparkles,
    title: "Modern Minimalist",
    desc: "Clean lines with elegant accents",
    colors: ["#2C3E50", "#E8E8E8", "#BDC3C7"],
    image: "https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?w=600"
  },
  {
    id: "destination",
    icon: Heart,
    title: "Destination Wedding",
    desc: "Beach, mountain, or garden romance",
    colors: ["#87CEEB", "#F0F8FF", "#FAF0E6"],
    image: "https://images.unsplash.com/photo-1510076857177-7470076d4098?w=600"
  },
  {
    id: "festive",
    icon: PartyPopper,
    title: "Festival Celebration",
    desc: "Vibrant colors and cultural richness",
    colors: ["#FF6B35", "#FFD93D", "#6BCB77"],
    image: "https://images.unsplash.com/photo-1530103862676-de8c9debad1d?w=600"
  }
];

const WeddingVision = () => {
  const [selectedStyle, setSelectedStyle] = useState(null);
  const [showPalette, setShowPalette] = useState(false);

  return (
    <section className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32 overflow-hidden" style={{ background: "linear-gradient(180deg, #faf8f5 0%, #ffffff 100%)" }}>
      {/* Background Pattern */}
      <div className="absolute inset-0 opacity-5">
        <div className="absolute inset-0" style={{
          backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23d4af37' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`,
        }} />
      </div>

      <div className="max-w-7xl mx-auto relative">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
        >
          <div className="flex items-center justify-center gap-3 mb-4">
            <motion.div
              animate={{ rotate: [0, 10, -10, 0] }}
              transition={{ duration: 2, repeat: Infinity }}
            >
              <Heart size={20} color="#d4af37" fill="#d4af37" />
            </motion.div>
            <span className="overline">Wedding Consultation</span>
            <motion.div
              animate={{ rotate: [0, -10, 10, 0] }}
              transition={{ duration: 2, repeat: Infinity }}
            >
              <Heart size={20} color="#d4af37" fill="#d4af37" />
            </motion.div>
          </div>
          <h2 style={{ fontSize: "clamp(36px, 4vw, 56px)", lineHeight: 1.1, fontWeight: 700, color: "#1a080a", fontFamily: "Outfit, sans-serif" }}>
            Discover Your <span style={{ color: "#d4af37", fontWeight: 700 }}>Wedding Style</span>
          </h2>
          <p className="mt-4 max-w-2xl mx-auto text-lg font-medium" style={{ color: "rgba(26,8,10,0.75)", lineHeight: 1.7 }}>
            Every wedding tells a unique story. Select your preferred style and let us curate the perfect fabric palette for your celebration.
          </p>
        </motion.div>

        {/* Style Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {WEDDING_STYLES.map((style, i) => (
            <motion.div
              key={style.id}
              className={`relative rounded-2xl overflow-hidden cursor-pointer ${selectedStyle?.id === style.id ? 'ring-4 ring-[#d4af37]' : ''}`}
              style={{ border: "2px solid rgba(212,175,55,0.3)", background: "#ffffff" }}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1, duration: 0.5 }}
              whileHover={{ y: -8, boxShadow: "0 20px 40px rgba(212,175,55,0.2)" }}
              onClick={() => {
                setSelectedStyle(style);
                setShowPalette(true);
              }}
            >
              {/* Image */}
              <div className="relative h-48 overflow-hidden">
                <motion.img
                  src={style.image}
                  alt={style.title}
                  className="w-full h-full object-cover"
                  whileHover={{ scale: 1.1 }}
                  transition={{ duration: 0.5 }}
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                <div className="absolute bottom-4 left-4 right-4">
                  <div className="flex items-center gap-2 mb-2">
                    {style.colors.map((color, idx) => (
                      <motion.div
                        key={idx}
                        className="w-6 h-6 rounded-full"
                        style={{ background: color, border: "2px solid white" }}
                        whileHover={{ scale: 1.2 }}
                      />
                    ))}
                  </div>
                </div>
              </div>

              {/* Content */}
              <div className="p-6">
                <div className="flex items-center gap-3 mb-3">
                  <motion.div
                    className="w-10 h-10 rounded-full flex items-center justify-center"
                    style={{ background: "linear-gradient(135deg, rgba(212,175,55,0.2), rgba(212,175,55,0.1))" }}
                    whileHover={{ rotate: 360 }}
                    transition={{ duration: 0.5 }}
                  >
                    <style.icon size={18} color="#d4af37" />
                  </motion.div>
                  <h3 className="text-xl font-bold" style={{ color: "#1a080a", fontFamily: "Outfit, sans-serif" }}>{style.title}</h3>
                </div>
                <p className="text-sm font-medium" style={{ color: "rgba(26,8,10,0.75)" }}>{style.desc}</p>
              </div>

              {/* Selected indicator */}
              {selectedStyle?.id === style.id && (
                <motion.div
                  className="absolute top-4 right-4 w-8 h-8 rounded-full flex items-center justify-center"
                  style={{ background: "#d4af37" }}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                >
                  <Sparkles size={16} color="white" />
                </motion.div>
              )}
            </motion.div>
          ))}
        </div>

        {/* Selected Style Details */}
        <AnimatePresence>
          {selectedStyle && showPalette && (
            <motion.div
              className="mt-12 p-8 rounded-2xl"
              style={{ background: "linear-gradient(135deg, #fffdf5, #fff9ed)", border: "2px solid rgba(212,175,55,0.3)" }}
              initial={{ opacity: 0, y: 30, height: 0 }}
              animate={{ opacity: 1, y: 0, height: "auto" }}
              exit={{ opacity: 0, y: -20 }}
            >
              <div className="flex flex-col md:flex-row items-center gap-8">
                <div className="flex-1">
                  <h3 className="text-2xl font-bold mb-3" style={{ color: "#1a080a", fontFamily: "Outfit, sans-serif" }}>
                    {selectedStyle.title} Collection
                  </h3>
                  <p className="mb-4 font-medium" style={{ color: "rgba(26,8,10,0.75)" }}>
                    We've curated premium fabrics that perfectly match your {selectedStyle.title.toLowerCase()} vision.
                  </p>
                  <div className="flex items-center gap-3 mb-4">
                    <span className="text-xs uppercase tracking-wider font-semibold" style={{ color: "rgba(26,8,10,0.6)" }}>Recommended Colors:</span>
                    {selectedStyle.colors.map((color, i) => (
                      <motion.div
                        key={i}
                        className="px-3 py-1 rounded-full text-xs font-semibold"
                        style={{ background: color, color: color === "#FFD700" || color === "#FFF8DC" || color === "#F5E6D3" || color === "#F0F8FF" ? "#1a080a" : "white" }}
                        whileHover={{ scale: 1.1 }}
                      >
                        {color}
                      </motion.div>
                    ))}
                  </div>
                </div>
                <div className="flex-shrink-0">
                  <motion.button
                    className="btn-gold px-8 py-4"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => window.open(`https://wa.me/919888919983?text=Hi! I'm interested in ${selectedStyle.title} style fabrics for my wedding.`, "_blank")}
                  >
                    <Sparkles size={18} className="mr-2" />
                    Get Custom Quote
                  </motion.button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </section>
  );
};

export default WeddingVision;
